+			value, next, err := searchFlagValue(args, i)
+			if err != nil {
+				return err
+			}
+			indexArgs = append(indexArgs, args[i], value)
+			i = next
+		default:
+			return unexpectedArgumentsError("health", opts.Version, []string{args[i]})
+		}
